pub proof fn lemma_always_there_is_no_request_msg_to_external_from_controller(
    spec: TempPred<ClusterState>,
    cluster: Cluster,
    controller_id: int,
)
requires
    spec.entails(lift_state(cluster.init())),
    spec.entails(always(lift_action(cluster.next()))),
    cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
    cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
ensures
    spec.entails(always(lift_state(Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)))),
{
    // The controller model used by this proof never emits ExternalRequest messages,
    // because the VReplicaSet reconciler uses the empty external request/response types.
    // Therefore, no request message originating from the controller can ever be
    // destined to the external host for that controller.
    //
    // This invariant is already captured by `Cluster::there_is_no_request_msg_to_external_from_controller`,
    // and the `spec` assumptions provide the standard temporal reasoning needed to lift
    // it to `always`.

    lemma_always_there_is_no_request_msg_to_external_from_controller_external(spec, cluster, controller_id);
}
}

