  3580	            &&& resources.contains_key(input.key)
  3581	            // and it has at least one owner reference
  3582	            &&& resources[key].metadata.owner_references is Some
  3583	            &&& resources[key].metadata.owner_references->0.len() > 0
  3584	            // The garbage collector decides whether to delete an object by checking its owner references,
  3585	            // it deletes the object if for each owner reference...
  3586	            &&& forall |i| #![trigger owner_references[i]] 0 <= i < owner_references.len() ==> {
  3587	                // the referred owner object does not exist in the cluster state
  3588	                ||| !resources.contains_key(owner_reference_to_object_reference(owner_references[i], key.namespace))
  3589	                // or it exists but has a different uid
  3590	                // (which means the actual owner was deleted and another object with the same name gets created again)
  3591	                ||| resources[owner_reference_to_object_reference(owner_references[i], key.namespace)].metadata.uid != Some(owner_references[i].uid)
