  3593	        },
  3594	        transition: |input: BuiltinControllersActionInput, s: ()| {
  3595	            // GC set the preconditions to the object's uid in its delete request
  3596	            // See https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/controller/garbagecollector/operations.go#L52-L61
  3597	            let preconditions = PreconditionsView {
  3598	                uid: input.resources[input.key].metadata.uid,
  3599	                resource_version: None,
  3600	            };
  3601	            let delete_req_msg = built_in_controller_req_msg(
  3602	                input.rpc_id_allocator.allocate().1, delete_req_msg_content(input.key, Some(preconditions))
  3603	            );
  3604	            let output = BuiltinControllersActionOutput {
  3605	                send: Multiset::singleton(delete_req_msg),
  3606	                rpc_id_allocator: input.rpc_id_allocator.allocate().0,
  3607	            };
  3608	            ((), output)
  3609	        },
  3610	    }
