3296	            // which is the current rv counter.
3297	            let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3298	            if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3299	                // Update fails.
